   158→    func eval_int_op(actual: i64, op: i32, expected: i64) -> bool {
   159→        if op == OP_EQ  { return actual == expected; }
   160→        if op == OP_NE  { return actual != expected; }
   161→        if op == OP_GT  { return actual > expected; }
   162→        if op == OP_LT  { return actual < expected; }
   163→        if op == OP_GE  { return actual >= expected; }
   164→        if op == OP_LE  { return actual <= expected; }
